                // Since we're dealing with intervals, we check if aInterval's range contains bInterval's range
                if (aInterval.min.compareTo(bInterval.min) > 0 || 
                    aInterval.max.compareTo(bInterval.max) < 0) {
                    return false;
                }
            }
        }
        return true;
    }

